			I[147] = new("ScrollingFrame", I[71], "diaryOfNamapo", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 4, BottomImageContent = Content.fromUri("rbxassetid://422202096"), CanvasSize = UDim2.fromScale(0, 1), MidImageContent = Content.fromUri("rbxassetid://422202096"), Position = UDim2.fromScale(0.35, 0.15), Size = UDim2.fromScale(0.3, 0.7), TopImageContent = Content.fromUri("rbxassetid://422202096"), Visible = false })
				I[148] = new("TextButton", I[147], "TextButton", { BackgroundColor3 = Color3.fromRGB(165, 57, 57), BorderSizePixel = 0, FontFace = Font.new("rbxasset://fonts/families/Arial.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal), Position = UDim2.new(1, -48, 0, 5), Size = UDim2.fromOffset(30, 30), Text = "x", TextColor3 = Color3.fromRGB(255, 255, 255), TextSize = 36 })
				I[149] = new("TextLabel", I[147], "Title", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 1, FontFace = Font.new("rbxasset://fonts/families/Arial.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal), Position = UDim2.fromScale(0, 0.94), Size = UDim2.new(1, -12, 0.04, 0), Text = "/u/namapo, 7/2/2014", TextScaled = true, TextSize = 14, TextWrapped = true })
				I[150] = new("TextLabel", I[147], "TextLabel", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 1, BorderSizePixel = 0, FontFace = Font.new("rbxasset://fonts/families/Arial.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal), Position = UDim2.new(0, 2, 0.78, 0), Size = UDim2.new(1, -12, 0.135, 0), Text = "Day 42: I was tazed again for the first time in ages. The guard had shot me, but before he could finish me off, he suddenly disappeared. I'm dying. The last thing I will say is \"Well, dinner's ready. See you all in hell.\"", TextScaled = true, TextSize = 14, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top })
				I[151] = new("TextLabel", I[147], "TextLabel", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 1, FontFace = Font.new("rbxasset://fonts/families/Arial.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal), Position = UDim2.new(0, 2, 0.65, 0), Size = UDim2.new(1, -12, 0.1, 0), Text = "Day 18: Like a certain Patrick Bateman, I got away scot free. All I had to do was walk into town, and they almost instantly accepted me. I fear they know who I am.", TextScaled = true, TextSize = 14, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top })
				I[152] = new("TextLabel", I[147], "TextLabel", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 1, FontFace = Font.new("rbxasset://fonts/families/Arial.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal), Position = UDim2.new(0, 2, 0.4, 0), Size = UDim2.new(1, -12, 0.22, 0), Text = "Day 18: A line of prisoners tried to make a ladder to get up over the gate. Dumbasses didn't see the giant sign that said it was electric. Climbed over the gate using their corpses. Ate a few. I'm in the woods now. I hear my name being called from afar \"namapo you're a noob why did you kill the guard\" \"namapo u git why did u not help us\". I can't make it stop, this symphony of guilt.", TextScaled = true, TextSize = 14, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top })
				I[153] = new("TextLabel", I[147], "TextLabel", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 1, FontFace = Font.new("rbxasset://fonts/families/Arial.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal), Position = UDim2.new(0, 2, 0.24, 0), Size = UDim2.new(1, -12, 0.13, 0), Text = "Day 6: Same guard that tazed the others went for me next. Found a convenient sledgehammer lying where any ol inmate could grab it. Knocked his head in. They will be looking for me now.", TextScaled = true, TextSize = 14, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top })
				I[154] = new("TextLabel", I[147], "Title", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 1, FontFace = Font.new("rbxasset://fonts/families/Arial.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal), Position = UDim2.fromScale(0, 0.03), Size = UDim2.new(1, -12, 0.05, 0), Text = "Diary of namapo", TextScaled = true, TextSize = 14, TextWrapped = true })
				I[155] = new("TextLabel", I[147], "TextLabel", { BackgroundColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 1, FontFace = Font.new("rbxasset://fonts/families/Arial.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal), Position = UDim2.new(0, 2, 0.1, 0), Size = UDim2.new(1, -12, 0.1, 0), Text = "Day 1: Alright, I showed up to the prison today, got fitted for my new clothes. First thing I saw was a guard taze some woman then shoot her with a shotgun point blank. This is gonna suck.", TextScaled = true, TextSize = 14, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top })
